 function importCurriculum(file:File){const r=new FileReader();r.onload=()=>{try{const x=JSON.parse(String(r.result));if(!Array.isArray(x.subjects))throw Error();const subjects:Subject[]=[],units:Unit[]=[],lessons:Lesson[]=[];for(const a of x.subjects){if(!a?.name)continue;const sid=a.id||id();subjects.push({id:sid,name:clean(String(a.name)),color:a.color||'#7C3AED',priority:['low','medium','high'].includes(a.priority)?a.priority:'medium'});for(const u of a.units||[]){if(!u?.name)continue;const uid=u.id||id();units.push({id:uid,subjectId:sid,name:clean(String(u.name))});for(const l of u.lessons||[]){if(!l?.name)continue;lessons.push({id:l.id||id(),unitId:uid,name:clean(String(l.name)),estimatedMinutes:Math.max(5,Number(l.estimatedMinutes)||45),status:'not_started',priority:['low','medium','high'].includes(l.priority)?l.priority:'medium'})}}}if(!subjects.length)throw Error();update({subjects,units,lessons});notify('تم استيراد المنهج بنجاح');setModal(null)}catch{notify('ملف المنهج غير صالح')}};r.readAsText(file)}
