 function Tasks(){let list=s.tasks.filter(t=>(!q||lessonMap[t.lessonId]?.name.toLowerCase().includes(q.toLowerCase()))&&(!filter.subject||s.units.find(u=>u.id===lessonMap[t.lessonId]?.unitId)?.subjectId===filter.subject)&&(!filter.status||t.status===filter.status)&&(!filter.priority||t.priority===filter.priority)&&(!filter.date||t.date===filter.date));return <section><Title title="المهام" sub="إدارة المهام مع البحث والفلاتر." action={<button className="primary" onClick={()=>setModal('task')}><Plus/> مهمة</button>}/><FilterBar subject={filter.subject} onSubject={v=>setFilter({...filter,subject:v})}/><div className="filterrow"><select value={filter.status} onChange={e=>setFilter({...filter,status:e.target.value})}><option value="">كل الحالات</option><option value="not_started">لم تبدأ</option><option value="in_progress">قيد التنفيذ</option><option value="completed">مكتملة</option><option value="skipped">متخطاة</option></select><select value={filter.priority} onChange={e=>setFilter({...filter,priority:e.target.value})}><option value="">كل الأولويات</option><option value="high">High</option><option value="medium">Medium</option><option value="low">Low</option></select><input type="date" value={filter.date} onChange={e=>setFilter({...filter,date:e.target.value})}/></div><div className="card table">{list.length?list.map(t=><TaskRow t={t} key={t.id}/>):<Empty text="لا توجد مهام مطابقة." action="أنشئ خطة" onClick={schedule}/>}</div></section>}
