 function Questions(){let list=s.questions.filter(x=>(!q||x.question.includes(q))&&(!filter.subject||x.subjectId===filter.subject)&&(!filter.difficulty||x.difficulty===filter.difficulty));return <section><Title title="بنك الأسئلة" sub="أسئلتك أنت فقط — لا يتم توليد أي سؤال." action={<button className="primary" onClick={()=>setModal('question')}><Plus/> سؤال</button>}/><div className="filterrow"><FilterBar subject={filter.subject} onSubject={v=>setFilter({...filter,subject:v})}/><select value={filter.difficulty} onChange={e=>setFilter({...filter,difficulty:e.target.value})}><option value="">كل الصعوبات</option><option value="easy">Easy</option><option value="medium">Medium</option><option value="hard">Hard</option></select></div><div className="card">{list.length?list.map(x=><div className="listrow" key={x.id}><div><b>{x.question}</b><span>{subMap[x.subjectId]?.name||''} • {x.difficulty} • {x.type}</span></div><button aria-label="حذف السؤال" onClick={()=>update({questions:s.questions.filter(y=>y.id!==x.id)})}><Trash2/></button></div>):<Empty text="لسه مفيش أسئلة." action="أضف أول سؤال" onClick={()=>setModal('question')}/>}</div><button className="primary quizbtn" onClick={startQuiz}>اختبار سريع</button>{quiz.length>0&&!quizDone&&<Quiz/>}{quizDone&&<div className="card quizresult"><h2>النتيجة: {quizScore}/{quiz.length}</h2><p className="muted">تم تسجيل الأخطاء التي اخترت أنك أخطأت فيها.</p><button onClick={()=>{setQuizDone(false);setQuiz([])}}>إغلاق</button></div>}</section>}
 function startQuiz(){const pool=[...s.questions].filter(x=>(!filter.subject||x.subjectId===filter.subject)&&(!filter.difficulty||x.difficulty===filter.difficulty)).sort(()=>Math.random()-.5).slice(0,Math.min(10,s.questions.length));if(!pool.length){notify('أضف أسئلة أولًا');return}setQuiz(pool);setQuizIndex(0);setQuizScore(0);setQuizDone(false)}
 function Quiz(){const cur=quiz[quizIndex];return <div className="overlay"><div className="modal"><span className="eyebrow">سؤال {quizIndex+1} من {quiz.length}</span><h2>{cur.question}</h2><p className="muted">الإجابة المحفوظة: {cur.answer}</p><div className="choices"><button onClick={()=>{setQuizScore(x=>x+1);nextQuiz()}}>إجابتي صحيحة</button><button onClick={()=>{update({mistakes:[...s.mistakes,{id:id(),questionId:cur.id,subjectId:cur.subjectId,question:cur.question,reason:'إجابة غير صحيحة',correctAnswer:cur.answer,notes:''}]});nextQuiz()}}>أخطأت</button></div></div></div>}
 function nextQuiz(){if(quizIndex+1>=quiz.length)setQuizDone(true);else setQuizIndex(x=>x+1)}
 function Mistakes(){let list=s.mistakes.filter(x=>(!q||x.question.includes(q))&&(!filter.subject||x.subjectId===filter.subject));return <section><Title title="دفتر الأخطاء" sub="سجل أخطاءك وسببها والإجابة الصحيحة." action={<button className="primary" onClick={()=>setModal('mistake')}><Plus/> تسجيل خطأ</button>}/><div className="filterrow"><FilterBar subject={filter.subject} onSubject={v=>setFilter({...filter,subject:v})}/></div><div className="card">{list.length?list.map(x=><div className="listrow" key={x.id}><div><b>{x.question}</b><span>{subMap[x.subjectId]?.name||''} • {x.reason} • {(x.status||'needs_review')==='fixed'?'تم الإصلاح':'يحتاج مراجعة'}</span><small>الإجابة الصحيحة: {x.correctAnswer}</small>{x.notes&&<small>{x.notes}</small>}</div><div className='actions'><button onClick={()=>update({mistakes:s.mistakes.map(y=>y.id===x.id?{...y,status:(y.status||'needs_review')==='fixed'?'needs_review':'fixed'}:y)})}>{(x.status||'needs_review')==='fixed'?'إرجاع للمراجعة':'تم الإصلاح'}</button><button onClick={()=>update({mistakes:s.mistakes.filter(y=>y.id!==x.id)})}><Trash2/></button></div></div>):<Empty text="دفتر الأخطاء فاضي." action="سجل أول خطأ" onClick={()=>setModal('mistake')}/>}</div></section>}
 function CalendarPage(){const y=calendarDate.getFullYear(),m=calendarDate.getMonth(),first=new Date(y,m,1),offset=first.getDay(),daysIn=new Date(y,m+1,0).getDate(),cells:Array<number|null>=Array.from({length:offset+daysIn},(_,i):number|null=>i<offset?null:i-offset+1);return <section><Title title="التقويم" sub="عدد المهام ووقت المذاكرة وحالة كل يوم." action={<div className="actions"><button onClick={()=>setCalendarDate(new Date(y,m-1,1))}><ChevronRight/></button><b>{calendarDate.toLocaleDateString(s.settings.language==='ar'?'ar-EG':'en',{month:'long',year:'numeric'})}</b><button onClick={()=>setCalendarDate(new Date(y,m+1,1))}><ChevronLeft/></button></div>}/><div className="calendar card">{['أحد','اثن','ثلا','أرب','خمي','جمع','سبت'].map(x=><b key={x}>{x}</b>)}{cells.map((day,i)=>{if(day===null)return <div key={'e'+i}/>;const ds=`${y}-${String(m+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`,ts=s.tasks.filter(t=>t.date===ds),done=ts.filter(t=>t.status==='completed').length,time=s.sessions.filter(a=>a.date===ds).reduce((a,z)=>a+z.duration,0);return <button className={'calday '+(ds===today()?'today':'')} key={ds} onClick={()=>setNotice(`${ds}: ${done}/${ts.length} مهام • ${time} دقيقة مذاكرة`)}><b>{day}</b><span>{ts.length} مهام</span><small>{time}د • {ts.length?Math.round(done/ts.length*100):0}%</small></button>})}</div></section>}
 function Focus(){
   const focusLessons=s.lessons.filter(l=>s.units.find(u=>u.id===l.unitId)?.subjectId===focusSubjectId);
  const selectedSubject=subMap[focusSubjectId]?.name||'';
  const selectedLesson=focusLessonId?lessonMap[focusLessonId]?.name||'':'';
  const setDuration=(raw:number)=>{
    const m=Math.min(180,Math.max(1,Math.round(Number(raw)||1)));
    setFocusMinutes(m);setFocusLeft(m*60);setFocusTotalSeconds(m*60);
    setFocusEnd(null);setRunning(false);
    try{localStorage.removeItem('thanaweya_focus_end')}catch{}
    update({settings:{...s.settings,focus:m}});
  };
  const startFocus=()=>{
   if(running){
    const remaining=Math.max(0,focusLeft);
    setFocusEnd(null);setRunning(false);
    try{localStorage.removeItem('thanaweya_focus_end')}catch{}
    setFocusLeft(remaining);
    return;
   }
   if(!focusSubjectId){
    notify(s.settings.language==='ar'?'اختار المادة الأول عشان نحفظ تقدمك بشكل صحيح.':'Choose a subject first so your progress is saved correctly.');
    return;
   }
   const seconds=Math.min(180*60,Math.max(1,Number(focusLeft)||focusMinutes*60));
   setFocusTotalSeconds(focusMinutes*60);
   const end=Date.now()+seconds*1000;
   setFocusLeft(seconds);setFocusEnd(end);
   try{localStorage.setItem('thanaweya_focus_end',String(end))}catch{}
   notify((s.settings.language==='ar'?'⏱️ بدأت جلسة ':'⏱️ Started a ')+selectedSubject+' session.');setRunning(true);
  };
  const reset=()=>{setRunning(false);setFocusEnd(null);try{localStorage.removeItem('thanaweya_focus_end')}catch{};setFocusLeft(focusMinutes*60);setFocusTotalSeconds(focusMinutes*60)};
  const quickDurations=[25,50,60,90,120];
  const mm=String(Math.floor(focusLeft/60)).padStart(2,'0'),ss=String(focusLeft%60).padStart(2,'0');
  return <section className={'focuspage '+(running?'runningFocus ':'')}>
   {running&&<div className="focusBackgroundOverlay" aria-hidden="true"/>}
   {running&&<div className="focusBlessing">صل على النبي ﷺ</div>}
   <div className="focusTopbar"><span className="eyebrow">FOCUS MODE</span></div>
   <h1>{mm}:{ss}</h1>
   <div className="focuscontext card">
    <label>المادة <select value={focusSubjectId} disabled={running} onChange={e=>{setFocusSubjectId(e.target.value);setFocusLessonId('')}}>
      <option value="">اختار المادة أولًا</option>{s.subjects.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}
    </select></label>
    <label>الدرس (اختياري) <select value={focusLessonId} disabled={running||!focusSubjectId} onChange={e=>setFocusLessonId(e.target.value)}>
      <option value="">بدون درس محدد</option>{focusLessons.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}
    </select></label>
    <label>مدة الجلسة: {focusMinutes} دقيقة
      <div className="quickDurations" aria-label="اختيارات مدة سريعة">
        {quickDurations.map(m=><button type="button" key={m} className={focusMinutes===m?'selected':''} disabled={running} onClick={()=>setDuration(m)}>{m} دقيقة</button>)}
      </div>
      <input type="number" min="1" max="180" step="1" value={focusMinutes} disabled={running} onChange={e=>setDuration(+e.target.value)} />
      <small className="muted">اختار مدة جاهزة بضغطة واحدة، أو اكتب مدة مخصصة لو محتاج.</small>
    </label>
   </div>
   <p>{selectedSubject?selectedSubject:'لا توجد مادة محددة'}{selectedLesson?' • '+selectedLesson:''}</p>
   <div className="focusring"><Timer size={44}/></div>
   <div className="focuscontrols">
    <button className="primary" onClick={startFocus} disabled={!running&&!focusSubjectId}>{running?<Pause/>:<Play/>}{running?'إيقاف':'ابدأ'}</button>
    <button onClick={reset}><RotateCcw/> إعادة</button>
   </div>
   <p className="muted">عند إنهاء الجلسة، هيتحفظ الوقت على المادة المختارة تلقائيًا. مدة الراحة: {s.settings.break} دقيقة</p>
  </section>
 } function Stats(){const bySub=s.subjects.map(x=>({name:x.name,min:s.sessions.filter(a=>a.subjectId===x.id).reduce((z,a)=>z+a.duration,0)}));const byDay=Array.from({length:7},(_,i)=>{const ds=addDays(today(),-6+i);return {ds,min:s.sessions.filter(a=>a.date===ds).reduce((z,a)=>z+a.duration,0)}});return <section><Title title="الإحصائيات" sub="كل الأرقام مبنية على بياناتك الفعلية."/><div className="statsgrid"><Stat title="إجمالي الوقت" value={totalMin+' دقيقة'} icon={<Timer/>}/><Stat title="الدروس المكتملة" value={s.lessons.filter(x=>x.status==='completed').length} icon={<BookOpen/>}/><Stat title="المهام المكتملة" value={s.tasks.filter(x=>x.status==='completed').length} icon={<CheckSquare/>}/><Stat title="الأسئلة" value={s.questions.length} icon={<FileQuestion/>}/><Stat title="Current Streak" value={streak} icon={<Trophy/>}/><Stat title="Longest Streak" value={longestStreak(s)} icon={<Trophy/>}/><Stat title="Overall Progress" value={progress+'%'} icon={<BarChart3/>}/></div><Card title="وقت المذاكرة حسب المادة">{bySub.map(x=><div className="barrow" key={x.name}><span>{x.name}</span><div><i style={{width:(totalMin?x.min/totalMin*100:0)+'%'}}/></div><b>{x.min}د</b></div>)}</Card><Card title="وقت المذاكرة آخر 7 أيام"><div className="weeklybars">{byDay.map(x=><div key={x.ds}><div className="vbar"><i style={{height:Math.min(100,x.min/Math.max(1,...byDay.map(y=>y.min))*100)+'%'}}/></div><small>{x.min}د</small></div>)}</div></Card></section>}
 function Achievements(){const doneTasks=s.tasks.filter(x=>x.status==='completed').length,defs=[['first','أول جلسة مذاكرة',s.sessions.length>0],['tasks10','أول 10 مهام',doneTasks>=10],['questions100','أول 100 سؤال',s.questions.length>=100],['streak3','3 أيام Streak',streak>=3],['streak7','7 أيام Streak',streak>=7],['streak30','30 يوم Streak',streak>=30],['week','أول أسبوع كامل',longestStreak(s)>=7],['subject','إنهاء أول مادة',s.subjects.some(sub=>{const ls=s.lessons.filter(l=>s.units.find(u=>u.id===l.unitId)?.subjectId===sub.id);return ls.length>0&&ls.every(l=>l.status==='completed')})],['half','إنهاء 50% من المنهج',progress>=50],['finish','إنهاء المنهج',progress===100&&s.lessons.length>0]];return <section><Title title="إنجازاتي" sub="تفتح تلقائيًا حسب بياناتك الحقيقية."/><div className="achievementGrid">{defs.map(([k,n,ok])=><div className={'achievement card '+(ok?'unlocked':'')} key={String(k)}><Trophy/><b>{n}</b><span>{ok?'مفتوح':'مغلق'}</span></div>)}</div></section>}
 function SettingsPage(){const[dragKey,setDragKey]=useState<string|null>(null),[dropKey,setDropKey]=useState<string|null>(null);const finishDrag=()=>{if(dragKey&&dropKey&&dragKey!==dropKey){const a=[...(s.settings.navOrder||nav.map(x=>x[0]))],fi=a.indexOf(dragKey),ti=a.indexOf(dropKey);if(fi>=0&&ti>=0){a.splice(fi,1);a.splice(ti,0,dragKey);update({settings:{...s.settings,navOrder:a}})}}setDragKey(null);setDropKey(null)};return <section><Title title="الإعدادات" sub="المظهر، الإشعارات، الحساب، الخطة والنسخ الاحتياطي."/><div className="settingsgrid"><Card title="ترتيب القائمة"><p className="muted">رتّب اختيارات القائمة الجانبية بالشكل اللي يناسبك. اسحب أي اختيار وحطه في المكان اللي يعجبك، والترتيب بيتحفظ تلقائيًا على جهازك.</p><div className="navOrderList">{nav.map(([k,n,I])=><div className={'navOrderItem '+(dragKey===k?'dragging':'')+(dropKey===k?' dropTarget':'')} data-key={String(k)} key={String(k)} onPointerDown={e=>{if(e.button!==0&&e.pointerType==='mouse')return;e.currentTarget.setPointerCapture?.(e.pointerId);setDragKey(k);setDropKey(k)}} onPointerMove={e=>{if(!dragKey)return;const el=document.elementFromPoint(e.clientX,e.clientY)?.closest<HTMLElement>('.navOrderItem');const target=el?.dataset.key;if(target)setDropKey(target)}} onPointerUp={finishDrag} onPointerCancel={finishDrag}><span><span className="dragHandle" aria-hidden="true">⋮⋮</span><I size={17}/><b>{n}</b></span></div>)}</div></Card><Card title="المظهر واللغة"><div className="choices"><button onClick={()=>update({settings:{...s.settings,theme:'dark'}})}><Moon/> Dark</button><button onClick={()=>update({settings:{...s.settings,theme:'light'}})}><Sun/> Light</button><button onClick={()=>update({settings:{...s.settings,theme:'system'}})}>System</button><button onClick={()=>update({settings:{...s.settings,language:s.settings.language==='ar'?'en':'ar'}})}><Globe2/> {s.settings.language==='ar'?'English':'العربية'}</button></div></Card><Card title="إعدادات المذاكرة"><label>وقت البداية<input type="time" value={s.settings.startTime} onChange={e=>update({settings:{...s.settings,startTime:e.target.value}})}/></label><label>مدة الجلسة<input type="number" min="5" value={s.settings.sessionMinutes} onChange={e=>update({settings:{...s.settings,sessionMinutes:+e.target.value}})}/></label><label>مدة الراحة<input type="number" min="1" value={s.settings.break} onChange={e=>update({settings:{...s.settings,break:+e.target.value}})}/></label><label>الحد الأدنى اليومي<input type="number" min="1" value={s.settings.minDailyMinutes} onChange={e=>update({settings:{...s.settings,minDailyMinutes:+e.target.value}})}/></label><label>عدد المهام اليومية<input type="number" min="1" value={s.settings.dailyTasks} onChange={e=>update({settings:{...s.settings,dailyTasks:+e.target.value}})}/></label><label>موعد الإشعارات<input type="time" value={s.settings.notificationTime} onChange={e=>update({settings:{...s.settings,notificationTime:e.target.value}})}/></label></Card><Card title="الإشعارات"><p className="muted">إشعارات المتصفح قد لا تعمل بعد إغلاق المتصفح بالكامل؛ السلوك يعتمد على الجهاز والمتصفح.</p><div className="toggles">{[['morning','إشعار بداية اليوم'],['study','إشعار بداية جلسة المذاكرة'],['overdue','إشعار المهام المتأخرة'],['review','إشعار المراجعة'],['endDay','إشعار نهاية اليوم']].map(([k,n])=><label key={String(k)}><input type="checkbox" checked={Boolean((s.settings as any)[k])} onChange={e=>update({settings:{...s.settings,[k]:e.target.checked}})}/>{n}</label>)}</div><button className="primary" onClick={askNotify}><Bell/> تفعيل الإشعارات</button></Card><Card title="نقل التقدم بين الأجهزة"><div className="transferBox"><b>انقل تقدمك للجهاز التاني بدون حساب</b><p className="muted">كل تقدمك محفوظ على الجهاز الحالي. أنشئ ملف نقل من هنا، ثم افتحه على الجهاز الجديد لاستعادة XP والـPoints والمهام والجلسات والأسئلة والأخطاء والإنجازات والإعدادات.</p><div className="actions"><button className="primary" onClick={exportData}><Download/> نقل تقدمي للجهاز الآخر</button><label className="upload"><Upload/> استيراد التقدم على هذا الجهاز<input type="file" accept="application/json" onChange={e=>e.target.files?.[0]&&importData(e.target.files[0])}/></label></div><div className="transferSteps"><b>طريقة النقل:</b><ol><li>من الجهاز القديم اضغط «نقل تقدمي للجهاز الآخر».</li><li>سيتم تنزيل ملف <code>thanaweya-os-backup.json</code>.</li><li>أرسل الملف للجهاز الجديد بأي طريقة مناسبة.</li><li>على الجهاز الجديد افتح Thanaweya OS ← الإعدادات ← «نقل التقدم بين الأجهزة».</li><li>اضغط «استيراد التقدم على هذا الجهاز» واختر الملف.</li></ol><small className="muted">تنبيه: الاستيراد يستبدل التقدم الموجود حاليًا على الجهاز الجديد.</small></div></div></Card><Card title="البيانات والنسخ الاحتياطي"><div className="actions"><button onClick={exportData}><Download/> Download Backup</button><label className="upload"><Upload/> Import Data<input type="file" accept="application/json" onChange={e=>e.target.files?.[0]&&importData(e.target.files[0])}/></label></div><button className="link" onClick={()=>setModal('curriculum')}>Import Curriculum JSON</button></Card><Card title="الملف الشخصي"><label>الاسم<input value={s.profile.name} onChange={e=>update({profile:{...s.profile,name:clean(e.target.value)}})}/></label><label>الصف<input value={s.profile.grade} onChange={e=>update({profile:{...s.profile,grade:clean(e.target.value)}})}/></label><label>الشعبة<input value={s.profile.section} onChange={e=>update({profile:{...s.profile,section:clean(e.target.value)}})}/></label><label>المدرسة (اختياري)<input value={s.profile.school} onChange={e=>update({profile:{...s.profile,school:clean(e.target.value)}})}/></label><label>الهدف الشخصي<textarea value={s.profile.goal} onChange={e=>update({profile:{...s.profile,goal:clean(e.target.value)}})}/></label></Card></div></section>}
 function TaskRow({t}:{t:Task;key?:any}){return <div className="taskrow"><button className={'check '+(t.status==='completed'?'done':'')} onClick={()=>completeTask(t)} aria-label="إكمال المهمة">{t.status==='completed'&&<Check size={16}/>}</button><div><b>{lessonMap[t.lessonId]?.name||'درس محذوف'}</b><span>{subMap[s.units.find(u=>u.id===lessonMap[t.lessonId]?.unitId)?.subjectId||'']?.name||''} • {t.estimatedMinutes} دقيقة • {t.date}</span></div><select className="taskstatus" value={t.status} onChange={e=>update({tasks:s.tasks.map(x=>x.id===t.id?{...x,status:e.target.value as Status}:x)})}><option value="not_started">لم تبدأ</option><option value="in_progress">قيد التنفيذ</option><option value="completed">مكتملة</option><option value="skipped">متخطاة</option></select></div>}
 function Card({title,children,action}:{title:string;children:any;action?:any}){return <div className="card"><div className="cardhead"><h2>{title}</h2>{action}</div>{children}</div>};function Stat({title,value,icon}:{title:string;value:any;icon:any}){return <div className="stat card"><div className="iconbox">{icon}</div><span>{title}</span><b>{value}</b></div>};function Title({title,sub,action}:{title:string;sub:string;action?:any}){return <div className="title"><div><h1>{title}</h1><p>{sub}</p></div>{action}</div>};function Empty({text,action,onClick}:{text:string;action?:string;onClick?:()=>void}){return <div className="empty"><div className="iconbox"><NotebookPen/></div><b>{text}</b>{action&&<button className="primary" onClick={onClick}>{action}</button>}</div>};function Modal({title,children}:{title:string;children:any}){return <div className="overlay" onClick={()=>setModal(null)}><div className="modal" onClick={e=>e.stopPropagation()}><div className="cardhead"><h2>{title}</h2><button aria-label="إغلاق" onClick={()=>setModal(null)}><X/></button></div>{children}</div></div>}
 function FilterBar({subject,onSubject}:{subject:string;onSubject:(v:string)=>void}){return <label className="filterlabel"><Filter size={15}/><select value={subject} onChange={e=>onSubject(e.target.value)}><option value="">كل المواد</option>{s.subjects.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label>}
