function NoteForm({subjects,lessons,onSave}:{subjects:Subject[];lessons:Lesson[];onSave:(x:Note)=>void}){const[t,setT]=useState(''),[c,setC]=useState(''),[sid,setSid]=useState(subjects[0]?.id||''),[lid,setLid]=useState('');return <form onSubmit={e=>{e.preventDefault();if(!t.trim()||!c.trim())return;onSave({id:id(),subjectId:sid,lessonId:lid||undefined,title:clean(t),content:clean(c),updatedAt:today()})}}><label>عنوان الملاحظة<input autoFocus value={t} onChange={e=>setT(e.target.value)}/></label><label>المحتوى<textarea value={c} onChange={e=>setC(e.target.value)}/></label><label>المادة<select value={sid} onChange={e=>setSid(e.target.value)}>{subjects.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><label>الدرس<select value={lid} onChange={e=>setLid(e.target.value)}><option value=''>بدون تحديد</option>{lessons.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><button className='primary wide'><Save/> حفظ</button></form>}
function LectureForm({subjects,units,lessons,onSave,initial}:{subjects:Subject[];units:Unit[];lessons:Lesson[];onSave:(x:any)=>void;initial?:Lecture}){const[title,setTitle]=useState(initial?.title||''),[sid,setSid]=useState(initial?.subjectId||subjects[0]?.id||''),[uid,setUid]=useState(initial?.unitId||''),[lid,setLid]=useState(initial?.lessonId||''),[kind,setKind]=useState<Lecture['kind']>(initial?.kind||'pdf'),[desc,setDesc]=useState(initial?.description||''),[url,setUrl]=useState(initial?.url||''),[file,setFile]=useState<File|null>(null),[saving,setSaving]=useState(false),[uploadPct,setUploadPct]=useState(0);const available=units.filter(u=>u.subjectId===sid);const hasUrl=!!url.trim();const submit=async()=>{if(!title.trim()||!sid)return;setSaving(true);setUploadPct(file?0:100);try{const meta:any={id:initial?.id||id(),title:clean(title),subjectId:sid,unitId:uid||undefined,lessonId:lid||undefined,kind,url:hasUrl?clean(url):undefined,description:clean(desc),fileName:hasUrl?undefined:(file?.name||initial?.fileName),size:hasUrl?undefined:(file?.size||initial?.size),createdAt:initial?.createdAt||today(),favorite:initial?.favorite||false};if(initial?.fileName&&(file||hasUrl))await deleteLectureFile(initial.id);if(file){const chunk=Math.max(256*1024,Math.ceil(file.size/40));let loaded=0;for(let start=0;start<file.size;start+=chunk){const part=file.slice(start,Math.min(file.size,start+chunk));await part.arrayBuffer();loaded=Math.min(file.size,start+chunk);setUploadPct(Math.round(loaded/file.size*90));await new Promise(r=>setTimeout(r,20))}await saveLectureFile(meta.id,file);setUploadPct(100)}onSave(meta)}finally{setSaving(false)}};return <form onSubmit={e=>{e.preventDefault();if(!saving)submit()}}><label>اسم المصدر<input autoFocus value={title} onChange={e=>setTitle(e.target.value)} placeholder="مثال: كتاب الفيزياء" disabled={saving}/></label><label>النوع<select value={kind} onChange={e=>setKind(e.target.value as Lecture['kind'])} disabled={saving}><option value="book">📕 كتاب</option><option value="pdf">📄 PDF</option><option value="lecture">🎥 محاضرة</option><option value="link">🔗 رابط</option><option value="notes">📝 ملزمة/ملاحظات</option><option value="other">📎 أخرى</option></select></label><label>المادة<select value={sid} onChange={e=>{setSid(e.target.value);setUid('');setLid('')}} disabled={saving}>{subjects.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><label>الوحدة (اختياري)<select value={uid} onChange={e=>{setUid(e.target.value);setLid('')}} disabled={saving}><option value="">بدون وحدة</option>{available.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><label>الدرس (اختياري)<select value={lid} onChange={e=>setLid(e.target.value)} disabled={saving}><option value="">بدون درس</option>{lessons.filter(l=>!uid||l.unitId===uid).map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><label>رابط الفيديو / المصدر (اختياري)<input type="url" value={url} onChange={e=>setUrl(e.target.value)} placeholder="https://youtube.com/... أو أي منصة تدعم التضمين" disabled={saving}/></label>{!hasUrl&&<label className="upload">📎 {initial?.fileName?'استبدال الملف (اختياري)':'اختر ملفًا (اختياري)'} — التحميل متاح بعد الحفظ<input type="file" accept=".pdf,.doc,.docx,.ppt,.pptx,.txt,.epub,.jpg,.jpeg,.png" onChange={e=>setFile(e.target.files?.[0]||null)} disabled={saving}/></label>}{saving&&<div className="uploadProgress"><b>صل على النبي ﷺ</b><div className="uploadProgressTrack"><i style={{width:uploadPct+'%'}}/></div><div className="uploadProgressMeta"><span>{file?'جاري تجهيز ورفع الملف...':'جاري الحفظ...'}</span><strong>{uploadPct}%</strong></div></div>}<label>وصف مختصر<textarea value={desc} onChange={e=>setDesc(e.target.value)} placeholder="محتوى المصدر أو ملاحظاتك" disabled={saving}/></label><button className="primary wide" disabled={saving||!title.trim()||!sid||(!hasUrl&&!file&&!initial?.fileName)}>{saving?<><RefreshCw className="spin"/> جاري الحفظ...</>:<><Save/> {initial?'حفظ التعديلات':'حفظ المصدر'}</>}</button></form>}
